function makeAction(overrides: Partial<CorrectiveAction> = {}): CorrectiveAction {
  return {
    id: 1,
    car_id: 1,
    action_type: 'IMMEDIATE',
    action_type_display: 'Immediate',
    description: 'Fix the issue with a detailed procedural action plan that exceeds fifty chars.',
    owner_crew_id: null,
    owner_user_id: null,
    owner_name: null,
    due_date: null,
    is_completed: false,
    completed_at: null,
    completion_remarks: null,
    sequence_no: 1,
    created_by: 'user1',
    created_date: '2026-01-01',
    ...overrides,
  };
}

function makeEvidence(overrides: Partial<Evidence> = {}): Evidence {
  return {
    id: 1,
    car_id: 1,
    evidence_type: 'BEFORE',
    evidence_type_display: 'Before',
    file_name: 'photo.jpg',
    file_path: '/uploads/photo.jpg',
    file_size: 1024,
    mime_type: 'image/jpeg',
    description: 'Before photo',
    uploaded_by: 'user1',
    uploaded_at: '2026-01-01',
    ...overrides,
  };
}

function futureDate() {
  const d = new Date();
  d.setDate(d.getDate() + 7);
  return d.toISOString().split('T')[0];
}

function yesterday() {
  const d = new Date();
  d.setDate(d.getDate() - 1);
  return d.toISOString().split('T')[0];
}

