describe('validateCarSubmission — happy path', () => {
  it('test_feat_car_004_happy_path_valid_submission_passes', () => {
    const result = validateCarSubmission(
      'A'.repeat(50),
      ['CLC-001'],
      null,
      [
        makeAction({ action_type: 'IMMEDIATE' }),
        makeAction({ action_type: 'LONG_TERM', id: 2 }),
      ],
      [
        makeEvidence({ evidence_type: 'BEFORE' }),
        makeEvidence({ evidence_type: 'AFTER', id: 2 }),
      ]
    );
    expect(result.valid).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

  it('test_feat_car_004_happy_path_custom_cause_instead_of_clc_passes', () => {
    const result = validateCarSubmission(
      'A'.repeat(50),
      [],
      'Custom root cause text',
      [
        makeAction({ action_type: 'IMMEDIATE' }),
        makeAction({ action_type: 'LONG_TERM', id: 2 }),
      ],
      [
        makeEvidence({ evidence_type: 'BEFORE' }),
        makeEvidence({ evidence_type: 'AFTER', id: 2 }),
      ]
    );
    expect(result.valid).toBe(true);
  });
});

